55|// One scene view: sub-pages, keys, buttons, progress, chapter jump.
56|// Sub-page moves stay in client state; scene moves push a new route.
57|export function ScenePage({
58|  view,
59|  views,
60|  bookId,
61|  textVersion,
62|  bookIndex,
63|  bookTotal,
64|  panels,
65|  nextChapter,
66|}: {
67|  view: SceneView;
68|  views: { sceneId: string; pages: number }[];
69|  bookId: string;
70|  textVersion: string;
71|  bookIndex: number;
72|  bookTotal: number;
73|  panels: ChapterPanel[];
74|  nextChapter: { ch: number; firstSceneId: string } | null;
75|}) {
76|  const pic = usePictures({ bookId, textVersion, sceneId: view.sceneId });
77|  const [pref, setPref] = useState<ImageStylePref>({ kind: "preset", id: "denslow" });
78|  const router = useRouter();
79|  const index = useMemo(() => buildNavIndex(views), [views]);
80|  const cover = view.isChapterFirst;
81|  const end = view.isChapterLast;
82|  const coverLong = coverTitleLong(view.chapterTitle);
83|  const total = subPageCount(view.pages.length, cover, end);
84|  const lastPage = total - 1;
85|  const [page, setPage] = useState(() => {
86|    if (enterAtEnd) {
87|      enterAtEnd = false;
88|      return lastPage;
89|    }
90|    return 0;
91|  });
92|  const [panelsOpen, setPanelsOpen] = useState(false);
93|  const [gateOpen, setGateOpen] = useState(false);
94|  const [offerAside, setOfferAside] = useState(() => chapterSetAside(view.ch));
95|  const gateOpener = useRef<HTMLElement | null>(null);
96|  const headingRef = useRef<HTMLHeadingElement>(null);
97|  const readColRef = useRef<HTMLDivElement | null>(null);
98|  const figEls = useRef(new Map<string, HTMLElement>());
99|  const kind = subPageKind(page, view.pages.length, cover, end);
100|  const sub = kind === "text" ? (view.pages[textPageAt(page, cover)] ?? view.pages[0]) : undefined;
101|  const textIndex = textPageAt(page, cover);
102|  const atStart = view.prevSceneId === null && page === 0;
103|  const atBookEnd = view.nextSceneId === null && page === lastPage;
104|
105|  useEffect(() => {
106|    setPref(loadImageStylePref());
107|  }, []);
108|
109|  // The end page marks the chapter finished, unlocking the panels.
110|  useEffect(() => {
111|    if (kind === "end") markChapterEndReached(view.ch);
112|  }, [kind, view.ch]);
113|
114|  function changePref(next: ImageStylePref) {
115|    setPref(next);
116|    saveImageStylePref(next);
117|  }
118|
119|  function requestPanels(opener: HTMLElement | null) {
120|    if (panelsUnlocked(view.ch)) {
121|      setPanelsOpen(true);
122|      return;
123|    }
124|    gateOpener.current = opener;
125|    setGateOpen(true);
126|  }
127|
128|  function showAnyway() {
129|    markPanelsShownAnyway(view.ch);
130|    setGateOpen(false);
131|    setPanelsOpen(true);
132|  }
133|
134|  function notYet() {
135|    setGateOpen(false);
136|    gateOpener.current?.focus?.();
137|    gateOpener.current = null;
138|  }
139|
140|  function readFirst() {
141|    markChapterSetAside(view.ch);
142|    setOfferAside(true);
143|  }
144|
145|  function goNextChapter() {
146|    if (!nextChapter) return;
147|    hasNavigated = true;
148|    router.push(`/leer/${nextChapter.firstSceneId}`);
149|  }
150|
151|  const figsByN = useMemo(() => {
152|    const grouped = new Map<number, InlineFigure[]>();
153|    for (const fig of pic.figures) {
154|      const list = grouped.get(fig.endN) ?? [];
155|      list.push(fig);
156|      grouped.set(fig.endN, list);
157|    }
158|    return grouped;
159|  }, [pic.figures]);
160|
161|  function pageOf(n: number): number {
162|    const found = view.pages.findIndex((p) => p.paragraphs.some((para) => para.n === n));
163|    return found;
164|  }
165|
166|  function gotoFigure(fig: InlineFigure) {
167|    const at = pageOf(fig.endN);
168|    if (at < 0) return;
169|    setPage(at + (cover ? 1 : 0));
170|    readColRef.current?.scrollTo(0, 0);
171|    requestAnimationFrame(() => {
172|      requestAnimationFrame(() => {
