41|// Read-only view of the session cache for the panels grid. Never
42|// writes, so it cannot change picture behaviour.
43|export function getCachedScenePicture(sceneId: string): { url: string; caption: string } | null {
44|  const hit = sceneCache.get(sceneId);
45|  return hit ? { url: hit.url, caption: hit.caption } : null;
46|}
47|const figureCache = new Map<string, InlineFigure[]>();
48|let figureSeq = 1;
49|
50|function paraOf(node: Node | null): Element | null {
51|  if (!node) return null;
52|  const el = node.nodeType === Node.TEXT_NODE ? node.parentElement : (node as Element);
53|  return el?.closest?.("p[id]") ?? null;
54|}
