56|async function postImage(body: unknown): Promise<ImageResponse> {
57|  const res = await fetch("/api/images", {
58|    method: "POST",
59|    headers: { "Content-Type": "application/json" },
60|    body: JSON.stringify(body),
61|  });
62|  return (await res.json()) as ImageResponse;
63|}
