65|async function poll(body: unknown): Promise<{ url: string; caption: string }> {
66|  let left = POLL_MAX;
67|  for (;;) {
68|    let res: ImageResponse;
69|    try {
70|      res = await postImage(body);
71|    } catch {
72|      throw new Error(MSG_FAILED);
73|    }
74|    if (res.status === "ready") return { url: res.url, caption: res.caption };
75|    if (res.status === "error") throw new Error(res.message);
76|    left -= 1;
77|    if (left <= 0) throw new Error(MSG_RETRY);
78|    await new Promise((done) => setTimeout(done, POLL_MS));
