88|  // The one bridge into the session: builds the context (clock, rng,
89|  // scene signals) and mirrors the view and a style change to state.
90|  const send = useCallback((intent: MusicIntent) => {
91|    const session = sessionRef.current;
92|    const fetched = manifestRef.current;
93|    if (!session || !fetched) return;
94|    const next = dispatch(session, intent, {
95|      manifest: fetched,
96|      signalOf: (sceneId) => byIdRef.current.get(sceneId) ?? null,
97|      routeSceneId: routeRef.current,
98|      nowSec: Date.now() / 1000,
99|      rng: Math.random,
100|    });
101|    sessionRef.current = next;
102|    if (next.view !== session.view) setView(next.view);
103|    if (next.selection !== session.selection) {
104|      saveMusicPrefs({
105|        style: next.selection.style,
106|        volume: volumeRef.current,
107|        muted: mutedRef.current,
108|      });
109|    }
110|  }, []);
111|
112|  // Stored prefs load once here, after the server-matching first render.
113|  // Saves happen only on user actions below, so the defaults above never
114|  // overwrite storage before this runs. The fetch below resolves later and
115|  // reads the style through the ref.
116|  useEffect(() => {
117|    const prefs = loadMusicPrefs();
118|    prefsRef.current = prefs;
119|    if (prefs !== null) {
120|      if (prefs.volume !== null) setVolume(prefs.volume);
121|      setMuted(prefs.muted);
122|    }
123|    try {
124|      setTheme(initialTheme(window.localStorage.getItem(THEME_KEY)));
125|    } catch {
