40|// Client container: bridges the music session to React state. It cues
41|// music on scene entry only, from the route id. Sub-page moves never
42|// reach the session. Params can lag a render, so the last observed id
43|// is compared before every scene entry.
44|export function Reader({
45|  scenes,
46|  chapters,
47|  bookTitle,
48|  bookAuthor,
49|  children,
50|}: {
51|  scenes: SlimScene[];
52|  chapters: ChapterJump[];
53|  bookTitle: string;
54|  bookAuthor: string;
55|  children: React.ReactNode;
56|}) {
57|  const routeParams = useParams();
58|  const router = useRouter();
59|  const param = routeParams?.sceneId;
60|  const routeSceneId = typeof param === "string" ? param : null;
61|  const [manifest, setManifest] = useState<MusicManifest | null>(null);
62|  const [view, setView] = useState<SessionView | null>(null);
63|  const [musicFailed, setMusicFailed] = useState(false);
64|  // Volume and mute persist next to the style in one prefs object; the
65|  // player stays a controlled view over them. State starts at the server
66|  // defaults so hydration matches, then a mount effect applies stored
67|  // prefs (parsed once) to volume, muted, and style via prefsRef.
68|  const [volume, setVolume] = useState(DEFAULT_VOLUME);
69|  const [muted, setMuted] = useState(false);
70|  const [theme, setTheme] = useState<"light" | "dark">("light");
71|  const [devOpen, setDevOpen] = useState(false);
72|  const prefsRef = useRef<PersistedMusicPrefs | null>(null);
73|  // Ref mirrors so send and persist handlers always read fresh values.
74|  const volumeRef = useRef(volume);
75|  volumeRef.current = volume;
76|  const mutedRef = useRef(muted);
77|  mutedRef.current = muted;
78|  const byId = useMemo(() => new Map(scenes.map((s) => [s.id, s.emotion])), [scenes]);
79|  const byIdRef = useRef(byId);
80|  byIdRef.current = byId;
81|  const manifestRef = useRef(manifest);
82|  manifestRef.current = manifest;
83|  const routeRef = useRef(routeSceneId);
84|  routeRef.current = routeSceneId;
85|  const sessionRef = useRef<MusicSession | null>(null);
86|  const observedRef = useRef<string | null>(null);
87|
88|  // The one bridge into the session: builds the context (clock, rng,
89|  // scene signals) and mirrors the view and a style change to state.
90|  const send = useCallback((intent: MusicIntent) => {
91|    const session = sessionRef.current;
92|    const fetched = manifestRef.current;
93|    if (!session || !fetched) return;
94|    const next = dispatch(session, intent, {
95|      manifest: fetched,
96|      signalOf: (sceneId) => byIdRef.current.get(sceneId) ?? null,
97|      routeSceneId: routeRef.current,
98|      nowSec: Date.now() / 1000,
99|      rng: Math.random,
100|    });
101|    sessionRef.current = next;
102|    if (next.view !== session.view) setView(next.view);
103|    if (next.selection !== session.selection) {
104|      saveMusicPrefs({
105|        style: next.selection.style,
106|        volume: volumeRef.current,
107|        muted: mutedRef.current,
108|      });
109|    }
110|  }, []);
111|
112|  // Stored prefs load once here, after the server-matching first render.
113|  // Saves happen only on user actions below, so the defaults above never
114|  // overwrite storage before this runs. The fetch below resolves later and
115|  // reads the style through the ref.
116|  useEffect(() => {
117|    const prefs = loadMusicPrefs();
118|    prefsRef.current = prefs;
119|    if (prefs !== null) {
120|      if (prefs.volume !== null) setVolume(prefs.volume);
121|      setMuted(prefs.muted);
122|    }
123|    try {
124|      setTheme(initialTheme(window.localStorage.getItem(THEME_KEY)));
125|    } catch {
126|      // The inline script already set a theme; keep the default.
127|    }
128|    if (new URLSearchParams(window.location.search).has("dev")) setDevOpen(true);
129|  }, []);
130|
131|  useEffect(() => {
132|    let cancelled = false;
133|    fetch("/music/manifest.json")
134|      .then((res) => {
135|        if (!res.ok) throw new Error(`manifest ${res.status}`);
136|        return res.json();
137|      })
138|      .then((json: unknown) => {
139|        if (cancelled) return;
140|        const parsed = parseManifest(json);
141|        setManifest(parsed);
142|        const session = startSession(parsed, prefsRef.current);
143|        sessionRef.current = session;
144|        setView(session.view);
145|      })
146|      .catch(() => {
147|        if (!cancelled) setMusicFailed(true);
148|      });
149|    return () => {
150|      cancelled = true;
151|    };
152|  }, []);
