155|  // lands. The first scene cues at once, so it plays on the first press.
156|  useEffect(() => {
157|    const gate = nextSceneEntry({
158|      observedId: observedRef.current,
159|      routeId: routeSceneId,
160|      manifestReady: manifest !== null,
161|    });
162|    observedRef.current = gate.nextObservedId;
163|    if (gate.shouldObserve && routeSceneId) send({ type: "sceneEntered", sceneId: routeSceneId });
164|  }, [routeSceneId, manifest, send]);
