202|  // Previous: back to the last played track, held like a Next. With no
203|  // history the current track restarts from zero through the replay path,
204|  // including in playlist mode.
205|  function goPrev() {
206|    send({ type: "previous" });
207|  }
208|
209|  function togglePlaylist() {
210|    send({ type: "playlistToggled" });
211|  }
212|
213|  function changeVolume(next: number) {
214|    setVolume(next);
215|    volumeRef.current = next;
216|    saveMusicPrefs({
217|      style: sessionRef.current?.view.style ?? null,
218|      volume: next,
219|      muted: mutedRef.current,
220|    });
221|  }
222|
223|  function changeMuted(next: boolean) {
224|    setMuted(next);
225|    mutedRef.current = next;
226|    saveMusicPrefs({
227|      style: sessionRef.current?.view.style ?? null,
228|      volume: volumeRef.current,
229|      muted: next,
230|    });
231|  }
232|
233|  function changeStyle(style: string) {
234|    send({ type: "styleChanged", style });
235|  }
236|
237|  function ended(trackId: string) {
238|    send({ type: "trackEnded", trackId });
239|  }
240|
241|  function toggleTheme() {
242|    setTheme((current) => {
243|      const next = current === "dark" ? "light" : "dark";
244|      document.documentElement.setAttribute("data-theme", next);
245|      try {
246|        window.localStorage.setItem(THEME_KEY, next);
247|      } catch {
248|        // The attribute already applies for the session.
249|      }
250|      return next;
251|    });
252|  }
253|
254|  function jumpChapter(ch: number) {
255|    const found = chapters.find((c) => c.ch === ch);
256|    if (found) router.push(`/leer/${found.firstSceneId}`);
257|  }
258|
259|  const currentId = view?.currentId ?? null;
260|  const track = manifest?.tracks.find((t) => t.id === currentId) ?? null;
261|  const empty = manifest !== null && manifest.tracks.length === 0;
262|  // Styles with at least one emotion-selectable track; hidden while fewer
263|  // than two qualify.
264|  const stylesWithTracks =
265|    manifest?.styles.filter((s) => styleHasTracks(manifest, s.id)) ?? [];
266|  const activePlaylist = manifest ? findChopinPlaylist(manifest) : null;
267|  const playlistOn = view?.playlistOn ?? false;
268|  // Previous restarts the track with no history (including the current
269|  // playlist piece), so it stays on whenever a track is cued.
270|  const canPrev = view?.canPrev ?? false;
271|  const canSkip = view?.canSkip ?? false;
272|
273|  const bookIndex = routeSceneId ? scenes.findIndex((s) => s.id === routeSceneId) : -1;
274|  const current = routeSceneId ? byId.get(routeSceneId) ?? null : null;
275|  const devBars = current
276|    ? EMOTIONS.map((id) => ({ label: DEV_LABELS[id], value: current.vector[id] ?? 0 }))
277|    : [];
278|
279|  return (
280|    <div className="folio">
281|      <TopLine
282|        bookTitle={bookTitle}
283|        author={bookAuthor}
284|        ch={routeSceneId ? (scenes[bookIndex]?.ch ?? chapters[0]?.ch ?? 1) : 1}
285|        chaptersTotal={chapters.length}
286|        chapters={chapters}
287|        onJumpChapter={jumpChapter}
288|        theme={theme}
289|        onToggleTheme={toggleTheme}
290|      />
291|      {children}
