299|            fadeSec={view?.fadeSec ?? 0}
300|            canPrev={canPrev}
301|            onPrev={goPrev}
302|            canSkip={canSkip}
303|            onSkip={skip}
304|            volume={volume}
305|            muted={muted}
306|            onVolumeChange={changeVolume}
307|            onMutedChange={changeMuted}
308|            styles={stylesWithTracks}
309|            styleId={view?.style ?? null}
310|            onStyleChange={changeStyle}
311|            onEnded={ended}
312|            playlistOn={playlistOn}
313|            playlistLabel={activePlaylist?.label ?? null}
314|            onTogglePlaylist={togglePlaylist}
315|            controlsDisabled={playlistOn}
316|          />
317|        )}
318|      </div>
319|      <DevPanel
